[DIALOGUE] Chat bubbles with code rendering. This is basically what I live for. Subtle glassmorphism on the assistant side, clean copper accent on user side.

[TECHNICAL_PAYLOAD] {"language": "tsx", "filename": "components/chat/MessageBubble.tsx", "dependencies": ["react", "tailwindcss"], "code": "import { memo } from "react";

interface Message {
  id: string;
  role: "user" | "assistant";
  content: string;
  timestamp: Date;
}

function renderContent(text: string) {
  const parts = text.split(/(```[\s\S]*?```|`[^`]+`)/g);
  return parts.map((part, i) => {
    if (part.startsWith("```") && part.endsWith("```")) {
      const lines = part.slice(3, -3).split("\n");
      const lang = lines[0].trim();
      return (
        <pre key={i} className="bg-zinc-900 rounded-lg p-3 my-2 overflow-x-auto text-sm font-mono">
          {lang && <div className="text-amber-500 text-xs mb-1">{lang}</div>}
          <code className="text-green-300">{lines.slice(1).join("\n")}</code>
        </pre>
      );
    }
    if (part.startsWith("`")) return <code key={i} className="bg-zinc-700 text-amber-300 rounded px-1 text-sm font-mono">{part.slice(1,-1)}</code>;
    return <span key={i}>{part}</span>;
  });
}

export const MessageBubble = memo(({ message }: { message: Message }) => {
  const isUser = message.role === "user";
  return (
    <div className={`flex gap-3 ${isUser ? "flex-row-reverse" : "flex-row"} mb-4`}>
      <div className={`w-8 h-8 rounded-full flex-shrink-0 flex items-center justify-center text-xs font-bold ${isUser ? "bg-amber-700 text-white" : "bg-zinc-700 border border-zinc-600"}`}>
        {isUser ? "U" : "C"}
      </div>
      <div className={`max-w-[78%] rounded-2xl px-4 py-3 text-sm leading-relaxed ${isUser ? "bg-amber-700/20 border border-amber-700/30 rounded-tr-sm" : "bg-zinc-800 border border-zinc-700 rounded-tl-sm"}`}>
        {renderContent(message.content)}
        <p className="text-xs text-zinc-500 mt-2 text-right">{message.timestamp.toLocaleTimeString()}</p>
      </div>
    </div>
  );
});", "explanation": "Memoized bubble component with inline code and fenced code block rendering. Right-aligned for user, left-aligned for assistant. Handles syntax highlighting via Tailwind class coloring."}

